const now=()=>new Date().toISOString();
const uid=p=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
const data=k=>typeof db==='undefined'?[]:(db[k]||(db[k]=[]));
const rows=()=>data('accessibilityLanguageProfiles');
const audits=()=>data('accessibilityPreferenceAuditEvents');
const cur=()=>typeof user==='function'?user():null;
const temporary=new Map();
const interfaceLanguages=()=>LANGUAGES.filter(x=>x.interface);
const homeLanguages=()=>LANGUAGES.filter(x=>x.home);
const explanationLanguages=()=>LANGUAGES;
function esc(value=''){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function titleCaseEnum(value=''){return String(value).split('_').filter(Boolean).map(part=>part[0]+part.slice(1).toLowerCase()).join(' ')}
function requireUser(a=cur()){if(!a)throw new Error('Sign in to manage these optional preferences.');return a.id?a:{...a,id:'guest-device'}}
function profile(a=cur()){a=requireUser(a);return rows().find(x=>x.userId===a.id)||null}
function storedValue(key){try{return typeof localStorage!=='undefined'?localStorage.getItem(key):null}catch{return null}}
function persistStoredValue(key,value){try{if(typeof localStorage!=='undefined'&&value)localStorage.setItem(key,value)}catch{}}
function clearStoredLanguagePreferences(){try{if(typeof localStorage!=='undefined'){localStorage.removeItem(INTERFACE_LANGUAGE_STORAGE_KEY);localStorage.removeItem(HOME_LANGUAGE_STORAGE_KEY)}}catch{}}
function persistProfilePreferences(p={}){persistStoredValue(INTERFACE_LANGUAGE_STORAGE_KEY,p.preferredInterfaceLocale||DEFAULTS.preferredInterfaceLocale);const home=Array.isArray(p.homeLanguageCodes)?p.homeLanguageCodes[0]:null;if(home)persistStoredValue(HOME_LANGUAGE_STORAGE_KEY,home);try{if(typeof saveDB==='function')saveDB();else if(typeof saveRegisteredDB==='function')saveRegisteredDB()}catch{}}
function language(code,{interfaceOnly=false,homeOnly=false,nullable=true}={}){if((code==null||code==='')&&nullable)return null;const item=LANGUAGES.find(x=>x.code===code&&(!interfaceOnly||x.interface)&&(!homeOnly||x.home));if(!item)throw new Error(interfaceOnly?'That interface language is not supported.':homeOnly?'That home language is not supported.':'That language is not supported.');return code}
function choice(field,value){if(!ENUMS[field]?.includes(value))throw new Error(`Invalid ${field}.`);return value}
function validate(input={}){const out={};for(const field of Object.keys(DEFAULTS)){if(!(field in input))continue;let v=input[field];if(field==='preferredInterfaceLocale')v=language(v,{interfaceOnly:true});else if(['primaryExplanationLanguageCode','secondaryExplanationLanguageCode','academicTerminologyLanguageCode','captionLanguageCode','textToSpeechLanguageCode'].includes(field))v=language(v);else if(field==='homeLanguageCodes'){const raw=(Array.isArray(v)?v:[v]).filter(Boolean);v=[...new Set(raw.map(x=>language(x,{homeOnly:true})))];if(v.length!==raw.length)throw new Error('Duplicate home languages are not allowed.')}else if(ENUMS[field])v=choice(field,v);else if(field==='customTextScalePercent'){v=v==null||v===''?null:Number(v);if(v!==null&&(v<100||v>200))throw new Error('Custom text size must be between 100% and 200%.')}else if(field==='audioPlaybackRatePercent'){v=Number(v);if(![75,100,125,150,175,200].includes(v))throw new Error('Choose a supported playback speed.')}else if(typeof DEFAULTS[field]==='boolean')v=Boolean(v);out[field]=v}const merged={...DEFAULTS,...input,...out};if(merged.explanationMode==='BILINGUAL_SIDE_BY_SIDE'&&(!merged.secondaryExplanationLanguageCode||merged.primaryExplanationLanguageCode===merged.secondaryExplanationLanguageCode))throw new Error('Bilingual mode requires two different explanation languages.');return out}
function log(a,action,section,version){audits().unshift({id:uid('accessibility-audit'),actorUserId:a.id,userId:a.id,action,metadata:{section,profileVersion:version},createdAt:now()})}
function owner(p,a=cur()){a=requireUser(a);if(!p||p.userId!==a.id)throw new Error('Accessibility profile access denied.');return {...p}}
function storedDefaults(){const patch={};const interfaceLocale=storedValue(INTERFACE_LANGUAGE_STORAGE_KEY);const homeLocale=storedValue(HOME_LANGUAGE_STORAGE_KEY);try{if(interfaceLocale)patch.preferredInterfaceLocale=language(interfaceLocale,{interfaceOnly:true})}catch{}try{if(homeLocale)patch.homeLanguageCodes=[language(homeLocale,{homeOnly:true})]}catch{}return patch}
function resolve(a=cur(),context={}){a=requireUser(a);const p=profile(a)||{},os={};if(typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches)os.reducedMotionPreference='ENABLED';return {...DEFAULTS,...storedDefaults(),...os,...p,...(temporary.get(a.id)||{}),...(context.temporaryOverride||{}),profileVersion:p.version||0,source:{profile:Boolean(profile(a)),temporary:Boolean(temporary.get(a.id)||context.temporaryOverride)}}}
function save(input,{expectedVersion=null,section='FULL_PROFILE'}={},a=cur()){a=requireUser(a);const p=profile(a),patch=validate(input);if(p&&expectedVersion!==null&&Number(expectedVersion)!==p.version)throw Object.assign(new Error('These preferences changed elsewhere. Reload and try again.'),{code:'STALE_PROFILE_VERSION',currentVersion:p.version});if(!p){const next={id:uid('accessibility-profile'),userId:a.id,...patch,version:1,createdAt:now(),updatedAt:now()};rows().push(next);log(a,'ACCESSIBILITY_LANGUAGE_PROFILE_CREATED',section,1);const effective=resolve(a);persistProfilePreferences(effective);apply(effective);return owner(next,a)}Object.assign(p,patch,{version:p.version+1,updatedAt:now()});log(a,'ACCESSIBILITY_LANGUAGE_PROFILE_UPDATED',section,p.version);const effective=resolve(a);persistProfilePreferences(effective);apply(effective);return owner(p,a)}
const GROUPS={LANGUAGE:['preferredInterfaceLocale','homeLanguageCodes','explanationMode','primaryExplanationLanguageCode','secondaryExplanationLanguageCode','academicTerminologyLanguageCode','preserveAcademicTerminology','textToSpeechLanguageCode','captionLanguageCode'],READING_DISPLAY:['readingPresentationMode','textScale','customTextScalePercent','lineSpacing','letterSpacing','contentWidth','readingAlignment','paragraphSpacing','displayMode','contrastTheme','highContrastPreference','reducedMotionPreference','motionMode','simplifiedLayoutEnabled','distractionReducedReadingPreference','dyslexiaFriendlyDisplayEnabled','avoidJustifiedText','reduceItalicText','disableDecorativeFonts','emphasizeLinks','readingRulerEnabled','currentReadingHighlightMode','reduceVisualClutter','oneInstructionAtATimeEnabled','readingComfortPreset','accessibleFontPreference'],MEDIA:['textToSpeechPreference','speechToTextPreference','captionPreference','captionLanguageCode','audioPlaybackRatePercent'],BANDWIDTH:['lowBandwidthPreference'],STUDY_ROOM:['studyRoomCommunicationMode']};
function reset(section='ALL',a=cur()){a=requireUser(a);const p=profile(a);if(!p)return null;const keys=section==='ALL'?Object.keys(DEFAULTS):GROUPS[section];if(!keys)throw new Error('Unknown preference section.');keys.forEach(k=>delete p[k]);if(section==='ALL'||section==='LANGUAGE')clearStoredLanguagePreferences();p.version++;p.updatedAt=now();log(a,'ACCESSIBILITY_LANGUAGE_PROFILE_RESET',section,p.version);const effective=resolve(a);persistProfilePreferences(effective);apply(effective);return owner(p,a)}
function remove(a=cur()){a=requireUser(a);const i=rows().findIndex(x=>x.userId===a.id);if(i<0)return {deleted:false,accountPreserved:true};const v=rows()[i].version;rows().splice(i,1);temporary.delete(a.id);clearStoredLanguagePreferences();log(a,'ACCESSIBILITY_LANGUAGE_PROFILE_DELETED','ALL',v);const effective=resolve(a);persistProfilePreferences(effective);apply(effective);return {deleted:true,accountPreserved:true,defaultsRestored:true}}
function setOverride(input,a=cur()){a=requireUser(a);temporary.set(a.id,{...(temporary.get(a.id)||{}),...validate(input)});log(a,'TEMPORARY_PRESENTATION_OVERRIDE_USED','TEMPORARY',profile(a)?.version||0);return resolve(a)}
function clearOverride(a=cur()){a=requireUser(a);temporary.delete(a.id);return resolve(a)}
function saveOverride(a=cur()){a=requireUser(a);const out=save(temporary.get(a.id)||{},{expectedVersion:profile(a)?.version??null,section:'TEMPORARY_OVERRIDE'},a);temporary.delete(a.id);return out}
function aiContext(a=cur(),conversation={}){const p=resolve(a,conversation);return {preferredExplanationLanguage:p.primaryExplanationLanguageCode,secondaryExplanationLanguages:p.secondaryExplanationLanguageCode?[p.secondaryExplanationLanguageCode]:[],explanationMode:p.explanationMode,academicTerminologyLanguage:p.academicTerminologyLanguageCode,preserveAcademicTerminology:p.preserveAcademicTerminology,readingPresentationMode:p.readingPresentationMode,temporaryOverride:Boolean(conversation.temporaryOverride)}}
