function equivalent(original,adapted){const keys=['subject','courseLevel','learningObjective','requiredTerminology','requiredReasoning','successCriteria'],changedFields=keys.filter(k=>JSON.stringify(original?.[k])!==JSON.stringify(adapted?.[k]));return {valid:!changedFields.length,rejected:Boolean(changedFields.length),changedFields}}
function translate(key,locale=currentInterfaceLocale()){const path=String(key).split('.');let current=INTERFACE_TRANSLATIONS[locale];for(const part of path)current=current?.[part];if(current!=null)return current;current=INTERFACE_TRANSLATIONS.en;for(const part of path)current=current?.[part];return current??key}
function translateInterfaceText(text,locale=currentInterfaceLocale()){const source=String(text||'').trim();if(!source||locale==='en')return source;return UI_TEXT_TRANSLATIONS[locale]?.[source]||source}
function currentInterfaceLocale(){const stored=storedValue(INTERFACE_LANGUAGE_STORAGE_KEY);try{if(stored)return language(stored,{interfaceOnly:true})}catch{}try{return resolve(cur()).preferredInterfaceLocale||'en'}catch{return (typeof document!=='undefined'&&document.documentElement?.lang)||'en'}}
function setText(node,text){if(!node)return;node.textContent=text}
function setAttr(node,name,value){if(node)node.setAttribute(name,value)}
function translateExactElementText(node,locale){if(!node||node.closest?.('[data-no-interface-translate]'))return;const source=(node.dataset?.i18nSource||node.textContent||'').trim();if(!source||source.length>320||node.childElementCount>0&&!node.matches('button'))return;const translated=translateInterfaceText(source,locale);if(translated!==source||node.dataset?.i18nSource){node.dataset.i18nSource=source;node.textContent=translated}}
function applyCommonInterfaceTranslations(locale){const scope=document.querySelector('#accessibilityLanguageContent');if(!scope)return;scope.querySelectorAll('h2,h3,p,legend,b,small,button,em,.access-control-label,.kicker').forEach(node=>translateExactElementText(node,locale))}
function applyInterfaceTranslations(p){if(typeof document==='undefined'||!document.documentElement)return;const locale=(p?.preferredInterfaceLocale)||currentInterfaceLocale(),lang=LANGUAGES.find(x=>x.code===locale&&x.interface)||LANGUAGES[0],root=document.documentElement;root.lang=lang.code;root.dir=lang.dir||'ltr';root.dataset.interfaceLocale=lang.code;document.body?.setAttribute('dir',root.dir);const navMap={'student-home':'Home','student-coach':'AI Coach','student-learn':'Learn','student-assignments':'Assignments','student-study-together':'Study Together','student-projects':'Projects','student-progress':'Progress',settings:'Settings',help:'Help'};for(const [id,key]of Object.entries(navMap)){const button=document.querySelector(`#appNav [data-nav-id="${id}"]`),label=translate(`nav.${key}`,lang.code);setText(button?.querySelector('.sidebar-nav-label'),label);setAttr(button,'aria-label',label);setAttr(button,'data-sidebar-tooltip',label)}const search=document.getElementById('globalSearchHeaderInput');if(search)setAttr(search,'placeholder',translate('chrome.search',lang.code));setAttr(document.getElementById('menuBtn'),'aria-label',translate('chrome.menu',lang.code));const note=document.querySelector('.notification-top-button');setAttr(note,'aria-label',translate('chrome.notifications',lang.code));setAttr(note,'title',translate('chrome.notifications',lang.code));setAttr(document.getElementById('topAvatar'),'aria-label',translate('chrome.account',lang.code));const active=document.querySelector('.app-view.active')?.id;if(active==='accessibilityLanguageView'){setText(document.getElementById('breadcrumb'),translate('chrome.breadcrumbAccount',lang.code));setText(document.getElementById('viewTitle'),translate('accessibility.pageTitle',lang.code));setText(document.querySelector('#accessibilityLanguageView .kicker'),translate('accessibility.kicker',lang.code));setText(document.getElementById('accessibility-language-title'),translate('accessibility.pageTitle',lang.code));setText(document.querySelector('#accessibilityLanguageView .view-intro p'),translate('accessibility.pageDescription',lang.code));applyCommonInterfaceTranslations(lang.code)}}
function apply(p){if(typeof document==='undefined'||!document.documentElement)return p;const root=document.documentElement,scale=p.textScale==='CUSTOM'?p.customTextScalePercent:{LARGE:125,EXTRA_LARGE:150}[p.textScale]||100;for(const [k,v] of Object.entries({displayMode:p.displayMode,highContrast:p.highContrastPreference,reducedMotion:p.reducedMotionPreference,dyslexiaFriendly:p.dyslexiaFriendlyDisplayEnabled,textScale:p.textScale,lineSpacing:p.lineSpacing,letterSpacing:p.letterSpacing,contentWidth:p.contentWidth,contrastTheme:p.contrastTheme,motionMode:p.motionMode,lowBandwidth:p.lowBandwidthPreference,readingRuler:p.readingRulerEnabled?'ON':'OFF',readingHighlight:p.currentReadingHighlightMode,visualClutter:p.reduceVisualClutter?'REDUCED':'STANDARD'}))root.dataset[k]=String(v);root.lang=p.preferredInterfaceLocale||'en';root.dir=LANGUAGES.find(x=>x.code===root.lang)?.dir||'ltr';document.body?.setAttribute('dir',root.dir);root.style.setProperty('--accessibility-text-scale',String(scale/100));root.style.setProperty('--studyspark-text-scale',String(scale/100));if(p.lowBandwidthPreference==='ENABLED')document.querySelectorAll('img').forEach(x=>x.loading='lazy');applyInterfaceTranslations(p);return p}
function preview(input,a=cur()){return {preferences:{...resolve(a),...validate(input)},academicSample:{subject:'Biology',courseLevel:'Grade 11',learningObjective:'Explain diffusion.',requiredTerminology:['diffusion','concentration gradient','passive transport'],requiredReasoning:'Connect particle motion to net movement.',successCriteria:'Give a causal explanation using required terms.'},saved:false}}
function optionLabel(field,value){return READING_OPTION_LABELS[field]?.[value]||titleCaseEnum(value)}
function segmentedControl(field,label,values,current,help=''){return `<div class="access-control-group" data-control-field="${esc(field)}"><p class="access-control-label" id="${esc(field)}-label">${esc(label)}</p>${help?`<p class="access-control-help" id="${esc(field)}-help">${esc(help)}</p>`:''}<div class="access-segment-grid" role="radiogroup" aria-labelledby="${esc(field)}-label" ${help?`aria-describedby="${esc(field)}-help"`:''}>${values.map(value=>`<button class="access-segment" type="button" role="radio" aria-checked="${value===current?'true':'false'}" data-pref-field="${esc(field)}" data-pref-value="${esc(value)}" data-selected="${value===current?'true':'false'}">${esc(optionLabel(field,value))}</button>`).join('')}</div><input type="hidden" name="${esc(field)}" value="${esc(current)}"></div>`}
function selectControl(field,label,values,current,help=''){return `<label class="access-control-group access-select-control"><span class="access-control-label">${esc(label)}</span>${help?`<span class="access-control-help">${esc(help)}</span>`:''}<select class="reading-control-select" name="${esc(field)}" data-reading-select="${esc(field)}">${values.map(value=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(optionLabel(field,value))}</option>`).join('')}</select></label>`}
function toggleControl(field,label,checked,help=''){return `<label class="access-toggle-card"><span><b>${esc(label)}</b>${help?`<small>${esc(help)}</small>`:''}</span><input type="checkbox" name="${esc(field)}" ${checked?'checked':''}></label>`}
function languageCards(field,items,current){return `<div class="language-card-grid" role="radiogroup" aria-labelledby="${field}-label">${items.map(item=>`<button class="language-option-card" type="button" role="radio" aria-checked="${item.code===current?'true':'false'}" data-language-field="${esc(field)}" data-language-code="${esc(item.code)}" data-selected="${item.code===current?'true':'false'}" lang="${esc(item.code)}" dir="${esc(item.dir||'ltr')}"><span class="language-option-icon" aria-hidden="true">${item.code==='ar'?'ع':item.code.startsWith('zh')?'文':item.code==='fr'?'Fr':item.code==='es'?'Es':'En'}</span><span><b>${esc(item.name)}</b><small>${esc(item.nativeName)}</small></span><em>${item.code===current?'Selected':'Choose'}</em></button>`).join('')}</div><input type="hidden" name="${esc(field)}" value="${esc(current)}">`}
function homeLanguage(p){const code=(Array.isArray(p.homeLanguageCodes)&&p.homeLanguageCodes[0])||p.secondaryExplanationLanguageCode||storedValue(HOME_LANGUAGE_STORAGE_KEY)||'en';return LANGUAGES.find(x=>x.code===code&&x.home)||LANGUAGES[0]}
function languagePreviewHTML(p){const interfaceLang=LANGUAGES.find(x=>x.code===p.preferredInterfaceLocale)||LANGUAGES[0],home=homeLanguage(p);return `<section class="language-preview-panel" id="languagePreviewPanel" aria-live="polite" aria-labelledby="languagePreviewTitle"><div><span class="kicker">LANGUAGE PREVIEW</span><h3 id="languagePreviewTitle">Compact language preview</h3></div><div class="language-preview-grid"><article lang="en" dir="ltr"><b>English sample</b><p>${esc(LANGUAGES[0].sample)}</p></article><article lang="${esc(home.code)}" dir="${esc(home.dir||'ltr')}"><b>${esc(home.name)} sample</b><p>${esc(home.sample)}</p></article><article lang="${esc(home.code)}" dir="${esc(home.dir||'ltr')}"><b>Important term translation</b><p><span>${esc(home.term)}</span> <span aria-hidden="true">→</span> <strong>${esc(home.termTranslation)}</strong></p></article></div><p class="language-preview-note">Interface language: <b>${esc(interfaceLang.name)}</b>. Home Language: <b>${esc(home.name)}</b>.</p></section>`}
function readingGroupHeading(icon,title){return `<div class="access-fieldset-heading"><span class="reading-comfort-icon" aria-hidden="true">${icon}</span><legend>${esc(title)}</legend></div>`}
function readingPreviewHTML(){return `<aside class="card reading-preview-card" id="readingPreviewCard" aria-labelledby="readingPreviewTitle"><div><span class="kicker">PREVIEW</span><h3 id="readingPreviewTitle">Reading Preview</h3><p>Changes here affect presentation only. Lessons, expectations, answers, and policies stay the same.</p></div><article class="reading-preview-sample" id="readingPreviewSample"><p>StudySpark can explain difficult ideas step by step. Adjust the settings until this paragraph feels comfortable to read.</p><p><em>Important academic terms</em> remain visible when explanations are simplified or translated.</p><div class="reading-preview-ruler" aria-hidden="true"></div></article></aside>`}
function readingComfortHTML(p){return `<div class="access-section-heading"><div><span class="kicker">READING COMFORT</span><h2 id="readingComfortTitle">Reading Comfort</h2><p>Adjust text, spacing, and reading aids until StudySpark feels comfortable to use. No diagnosis is required, and these settings do not change lesson content.</p></div></div><div class="reading-preset-row" aria-labelledby="readingPresetLabel"><div class="reading-preset-title-row"><div><p id="readingPresetLabel" class="access-control-label">Quick Presets</p><p class="access-control-help">Choose a starting point, then fine-tune any setting.</p></div><p class="reading-active-preset" aria-live="polite">Active preset: ${esc(READING_COMFORT_PRESETS[p.readingComfortPreset]?.label||'Custom')}</p></div><div class="reading-preset-grid reading-preset-grid--compact" role="radiogroup" aria-labelledby="readingPresetLabel">${['DEFAULT','COMFORTABLE_READING','REDUCED_DISTRACTION','HIGH_CONTRAST'].map(key=>{const item=READING_COMFORT_PRESETS[key];return `<button class="reading-preset-card" type="button" role="radio" aria-checked="${p.readingComfortPreset===key?'true':'false'}" data-reading-preset="${esc(key)}" data-selected="${p.readingComfortPreset===key?'true':'false'}"><b>${esc(item.label)}</b></button>`}).join('')}</div><button class="reading-suggested-link" type="button" data-reading-preset="COMFORTABLE_READING">Try Suggested Reading Settings</button><input type="hidden" name="readingComfortPreset" value="${esc(p.readingComfortPreset)}"></div><div class="reading-comfort-layout"><div class="reading-comfort-controls"><fieldset class="access-fieldset">${readingGroupHeading('T','Text Appearance')}${selectControl('accessibleFontPreference','Reading font',['SYSTEM','STUDYSPARK_DEFAULT','HUMANIST_SANS','READABLE_SERIF'],p.accessibleFontPreference,'Choose a readable font for StudySpark text.')}${segmentedControl('textScale','Text size',['SYSTEM','SMALL','MEDIUM','LARGE','EXTRA_LARGE'],p.textScale)}${toggleControl('reduceItalicText','Reduce italic text',p.reduceItalicText,'Use upright text where StudySpark can safely adjust presentation.')}${toggleControl('disableDecorativeFonts','Reduce decorative fonts',p.disableDecorativeFonts,'Prefer simpler fonts for decorative headings and labels.')}</fieldset><fieldset class="access-fieldset">${readingGroupHeading('≡','Word and Line Spacing')}${segmentedControl('wordSpacingPreference','Word spacing',['DEFAULT','RELAXED','EXPANDED'],p.wordSpacingPreference)}${segmentedControl('letterSpacing','Letter spacing',['DEFAULT','RELAXED','EXPANDED'],p.letterSpacing)}${segmentedControl('lineSpacing','Line spacing',['DEFAULT','RELAXED','EXPANDED','EXTRA_EXPANDED'],p.lineSpacing)}${segmentedControl('paragraphSpacing','Paragraph spacing',['DEFAULT','RELAXED','EXPANDED'],p.paragraphSpacing)}${segmentedControl('contentWidth','Content width',['SYSTEM','SHORT','COMFORTABLE','WIDE','FULL'],p.contentWidth)}</fieldset><fieldset class="access-fieldset">${readingGroupHeading('◉','Focus and Visual Clutter')}${toggleControl('reduceVisualClutter','Reduce visual clutter',p.reduceVisualClutter,'Simplifies decorative extras where possible.')}${segmentedControl('currentReadingHighlightMode','Highlight current reading area',['OFF','CURRENT_PARAGRAPH','CURRENT_LINE'],p.currentReadingHighlightMode)}${toggleControl('oneInstructionAtATimeEnabled','One instruction at a time',p.oneInstructionAtATimeEnabled,'Shows complex instructions in smaller steps when supported.')}</fieldset><fieldset class="access-fieldset reading-ruler-fieldset">${readingGroupHeading('▭','Reading Ruler')}${toggleControl('readingRulerEnabled','Reading ruler',p.readingRulerEnabled,'Shows a visual guide for the current reading area.')}<p class="reading-ruler-conditional-note" data-ruler-note>Turn on Reading Ruler to choose its style and size.</p><div class="reading-ruler-options" data-ruler-details>${segmentedControl('readingRulerStyle','Reading ruler style',['HIGHLIGHT_BAND','FOCUS_STRIP','DIM_SURROUNDING_CONTENT'],p.readingRulerStyle)}${segmentedControl('readingRulerSize','Reading ruler size',['SMALL','MEDIUM','LARGE'],p.readingRulerSize)}</div></fieldset><div class="reading-comfort-reset-row"><button class="btn btn-secondary" id="resetReadingComfort" type="button">Reset Reading Comfort</button></div></div>${readingPreviewHTML()}</div>`}
function upgradeReadingComfortMarkup(root,p){const section=root.querySelector('.reading-comfort-section');if(section&&!section.dataset.readingComfortUpgraded){section.dataset.readingComfortUpgraded='true';section.innerHTML=readingComfortHTML(p);const ruler=section.querySelector('input[name="readingRulerEnabled"]'),fieldset=section.querySelector('.reading-ruler-fieldset');if(fieldset)fieldset.dataset.rulerEnabled=ruler?.checked?'true':'false';ruler?.addEventListener('change',()=>{if(fieldset)fieldset.dataset.rulerEnabled=ruler.checked?'true':'false'})}}
function render(){const root=document.querySelector('#accessibilityLanguageContent'),a=cur();if(!root)return;if(!a){root.innerHTML='<div class="card access-pref-hero"><h2>Sign in required</h2><p>This optional profile is never required to use StudySpark. Sign in or continue in Guest Mode to save device preferences.</p></div>';applyInterfaceTranslations();return}const p=resolve(a),saved=profile(a),home=homeLanguage(p);root.innerHTML=`<div class="accessibility-language-page"><section class="card access-pref-hero"><span class="kicker">OPTIONAL AND PRIVATE</span><h2>Choose how StudySpark presents information</h2><p>Every setting is optional. You do not need to disclose a disability, diagnosis, or reason. These settings do not lower academic level, learning goals, reasoning, or expectations.</p><button class="btn btn-secondary" id="skipAccessPrefs" type="button">Skip for now</button></section><form id="accessPrefsForm" class="access-pref-form" data-redesigned-accessibility-language="true" novalidate><section class="card access-language-section" aria-labelledby="languagePrefsTitle"><div class="access-section-heading"><div><span class="kicker">LANGUAGE PREFERENCES</span><h2 id="languagePrefsTitle">Language Preferences</h2><p>Choose the language used for the interface and the language used for bilingual learning support.</p></div></div><div class="language-preference-grid"><section class="language-preference-card" aria-labelledby="preferredInterfaceLocale-label"><h3 id="preferredInterfaceLocale-label">Interface Language</h3><p>Changes menus, buttons, settings, and navigation throughout StudySpark.</p>${languageCards('preferredInterfaceLocale',interfaceLanguages(),p.preferredInterfaceLocale)}</section><section class="language-preference-card" aria-labelledby="homeLanguageCode-label"><h3 id="homeLanguageCode-label">Home Language</h3><p>Used for bilingual explanations, translated academic vocabulary, and Language Bridge support.</p>${languageCards('homeLanguageCode',homeLanguages(),home.code)}</section></div>${languagePreviewHTML(p)}<input type="hidden" name="explanationMode" value="${home.code===p.preferredInterfaceLocale?'USE_INTERFACE_LANGUAGE':'BILINGUAL_SIDE_BY_SIDE'}"><input type="hidden" name="primaryExplanationLanguageCode" value="${esc(p.preferredInterfaceLocale||'en')}"><input type="hidden" name="secondaryExplanationLanguageCode" value="${home.code===p.preferredInterfaceLocale?'':esc(home.code)}"><input type="hidden" name="academicTerminologyLanguageCode" value="${esc(home.code)}"><input type="hidden" name="textToSpeechLanguageCode" value="${esc(home.code)}"><input type="hidden" name="captionLanguageCode" value="${esc(home.code)}"><label class="access-toggle-card access-terminology-toggle"><span><b>Preserve required academic terminology</b><small>Important school terms remain visible even when explanations are bilingual or translated.</small></span><input type="checkbox" name="preserveAcademicTerminology" ${p.preserveAcademicTerminology?'checked':''}></label></section><section class="card reading-comfort-section" aria-labelledby="readingComfortTitle"><div class="access-section-heading"><div><span class="kicker">READING COMFORT</span><h2 id="readingComfortTitle">Reading Comfort</h2><p>Adjust how text appears so reading feels clearer and more comfortable.</p></div></div><div class="reading-preset-row" aria-labelledby="readingPresetLabel"><p id="readingPresetLabel" class="access-control-label">Reading comfort preset</p><div class="reading-preset-grid" role="radiogroup" aria-labelledby="readingPresetLabel">${Object.entries(READING_COMFORT_PRESETS).map(([key,item])=>`<button class="reading-preset-card" type="button" role="radio" aria-checked="${p.readingComfortPreset===key?'true':'false'}" data-reading-preset="${esc(key)}" data-selected="${p.readingComfortPreset===key?'true':'false'}"><b>${esc(item.label)}</b><small>${key==='DEFAULT'?'Use StudySpark’s standard display.':key==='COMFORTABLE_READING'?'Slightly roomier text for everyday reading.':key==='HIGH_CONTRAST'?'Stronger contrast and focus support.':key==='REDUCED_DISTRACTION'?'Wider spacing with fewer visual distractions.':'Fine-tune each reading setting yourself.'}</small></button>`).join('')}</div><input type="hidden" name="readingComfortPreset" value="${esc(p.readingComfortPreset)}"></div><div class="reading-comfort-layout"><div class="reading-comfort-controls"><fieldset class="access-fieldset"><legend>Text Appearance</legend>${segmentedControl('textScale','Text size',['SYSTEM','SMALL','MEDIUM','LARGE','EXTRA_LARGE'],p.textScale)}${segmentedControl('accessibleFontPreference','Font option',['SYSTEM','STUDYSPARK_DEFAULT','HUMANIST_SANS','READABLE_SERIF'],p.accessibleFontPreference)}${segmentedControl('contrastTheme','Contrast theme',['SYSTEM','STANDARD','HIGH_CONTRAST_LIGHT','HIGH_CONTRAST_DARK'],p.contrastTheme)}</fieldset><fieldset class="access-fieldset"><legend>Spacing and Layout</legend>${segmentedControl('lineSpacing','Line spacing',['DEFAULT','RELAXED','EXPANDED','EXTRA_EXPANDED'],p.lineSpacing)}${segmentedControl('letterSpacing','Letter spacing',['DEFAULT','RELAXED','EXPANDED'],p.letterSpacing)}${segmentedControl('contentWidth','Content width',['SYSTEM','SHORT','COMFORTABLE','WIDE','FULL'],p.contentWidth)}${segmentedControl('paragraphSpacing','Paragraph spacing',['DEFAULT','RELAXED','EXPANDED'],p.paragraphSpacing)}</fieldset><fieldset class="access-fieldset"><legend>Reading Assistance</legend>${toggleControl('readingRulerEnabled','Reading ruler',p.readingRulerEnabled,'Shows a visual guide for the current reading area.')}${toggleControl('currentReadingHighlightEnabled','Highlight current line',p.currentReadingHighlightMode==='CURRENT_LINE','Keeps the current line easier to find.')}${toggleControl('reduceVisualClutter','Reduce visual clutter',p.reduceVisualClutter,'Simplifies decorative extras where possible.')}${toggleControl('reducedMotionEnabled','Reduced motion',p.reducedMotionPreference==='ENABLED'||p.motionMode==='REDUCED_MOTION','Reduces animation and movement.')}${toggleControl('oneInstructionAtATimeEnabled','One instruction at a time',p.oneInstructionAtATimeEnabled,'Shows complex instructions in smaller steps when supported.')}</fieldset></div>${readingPreviewHTML()}</div></section><section class="card access-save-section" aria-labelledby="accessSaveTitle"><div><h2 id="accessSaveTitle">Save and Reset Actions</h2><p>Your preferences are private, optional, and can be changed at any time.</p></div><div id="accessPrefsErrors" class="form-errors" role="alert"></div><div class="access-pref-actions"><button class="btn btn-primary" id="saveAccessPrefs" type="submit">Save Preferences</button><button class="btn btn-secondary" id="previewAccessPrefs" type="button">Preview</button><button class="btn btn-secondary" id="resetAccessPrefs" type="button" ${saved?'':'disabled'}>Reset</button><button class="btn btn-secondary" id="retryAccessPrefs" type="button" hidden>Retry Save</button></div><p id="accessPrefsStatus" role="status" aria-live="polite">${saved?'Saved':'No profile exists. Accessible defaults remain active.'}</p></section></form></div>`;bind(root);applyReadingPreview(root,readForm(root.querySelector('#accessPrefsForm')));applyInterfaceTranslations(p)}
function readForm(form){const values={};if(!form)return values;const formData=new FormData(form);for(const [key,value] of formData.entries())values[key]=value;const interfaceLocale=values.preferredInterfaceLocale||DEFAULTS.preferredInterfaceLocale,homeCode=values.homeLanguageCode||interfaceLocale;values.homeLanguageCodes=homeCode?[homeCode]:[];values.primaryExplanationLanguageCode=interfaceLocale;values.secondaryExplanationLanguageCode=homeCode&&homeCode!==interfaceLocale?homeCode:null;values.academicTerminologyLanguageCode=homeCode||interfaceLocale;values.textToSpeechLanguageCode=homeCode||interfaceLocale;values.captionLanguageCode=homeCode||null;values.explanationMode=homeCode&&homeCode!==interfaceLocale?'BILINGUAL_SIDE_BY_SIDE':'USE_INTERFACE_LANGUAGE';['preserveAcademicTerminology','readingRulerEnabled','reduceVisualClutter','oneInstructionAtATimeEnabled','reduceItalicText','disableDecorativeFonts'].forEach(k=>values[k]=Boolean(form.elements[k]?.checked));if(form.elements.currentReadingHighlightEnabled)values.currentReadingHighlightMode=form.elements.currentReadingHighlightEnabled.checked?'CURRENT_LINE':'OFF';values.reducedMotionPreference=form.elements.reducedMotionEnabled?.checked?'ENABLED':'SYSTEM';values.motionMode=form.elements.reducedMotionEnabled?.checked?'REDUCED_MOTION':'SYSTEM';return values}
function setStatus(status,text,kind=''){if(!status)return;status.dataset.i18nSource=text;status.textContent=translateInterfaceText(text,currentInterfaceLocale());status.dataset.statusKind=kind}
function setErrors(errors,text=''){if(errors)errors.textContent=text}
function setRadioState(container,selector,match){container.querySelectorAll(selector).forEach(button=>{const selected=match(button);button.dataset.selected=selected?'true':'false';button.setAttribute('aria-checked',String(selected));const em=button.querySelector('em');if(em)em.textContent=selected?'Selected':'Choose'})}
function applyLanguageSelection(root,field,code){const form=root.querySelector('#accessPrefsForm');const hidden=form?.elements[field];if(hidden)hidden.value=code;const p=readForm(form);updateLanguagePreview(root,p);applyInterfaceTranslations(p);setRadioState(root,`[data-language-field="${field}"]`,button=>button.dataset.languageCode===code)}
function updateLanguagePreview(root,values){const panel=root.querySelector('#languagePreviewPanel');if(!panel)return;const p={...resolve(cur()),...values};panel.outerHTML=languagePreviewHTML(p)}
function applyReadingPreview(root,values){const sample=root.querySelector('#readingPreviewSample');if(!sample)return;const scale={SMALL:.9,MEDIUM:1,LARGE:1.18,EXTRA_LARGE:1.32}[values.textScale]||1;const line={DEFAULT:1.55,RELAXED:1.75,EXPANDED:1.95,EXTRA_EXPANDED:2.15}[values.lineSpacing]||1.55;const letter={DEFAULT:'normal',RELAXED:'.035em',EXPANDED:'.07em'}[values.letterSpacing]||'normal';const word={DEFAULT:'normal',RELAXED:'.08em',EXPANDED:'.14em'}[values.wordSpacingPreference]||'normal';const paragraph={DEFAULT:'.85rem',RELAXED:'1.15rem',EXPANDED:'1.45rem'}[values.paragraphSpacing]||'.85rem';const width={SHORT:'52ch',COMFORTABLE:'64ch',WIDE:'78ch',FULL:'100%'}[values.contentWidth]||'68ch';sample.style.fontSize=`calc(1rem * ${scale})`;sample.style.lineHeight=String(line);sample.style.letterSpacing=letter;sample.style.wordSpacing=word;sample.style.maxWidth=width;sample.style.setProperty('--reading-preview-paragraph-gap',paragraph);sample.dataset.contrast=values.contrastTheme||'SYSTEM';sample.dataset.clutter=values.reduceVisualClutter?'reduced':'standard';sample.dataset.ruler=values.readingRulerEnabled?'on':'off';sample.dataset.rulerStyle=values.readingRulerStyle||'HIGHLIGHT_BAND';sample.dataset.rulerSize=values.readingRulerSize||'MEDIUM';sample.dataset.highlight=values.currentReadingHighlightMode||'OFF';sample.dataset.reduceItalic=values.reduceItalicText?'true':'false';sample.dataset.reduceDecorative=values.disableDecorativeFonts?'true':'false';sample.classList.toggle('reading-preview-humanist',values.accessibleFontPreference==='HUMANIST_SANS');sample.classList.toggle('reading-preview-serif',values.accessibleFontPreference==='READABLE_SERIF');root.querySelectorAll('.reading-ruler-fieldset').forEach(el=>{el.dataset.rulerEnabled=values.readingRulerEnabled?'true':'false'});const active=root.querySelector('.reading-active-preset');if(active)active.textContent=`Active preset: ${READING_COMFORT_PRESETS[values.readingComfortPreset]?.label||'Custom'}`}
