function bind(root){const form=root.querySelector('#accessPrefsForm'),status=root.querySelector('#accessPrefsStatus'),errors=root.querySelector('#accessPrefsErrors'),retry=root.querySelector('#retryAccessPrefs');if(!form)return;upgradeReadingComfortMarkup(root,{...resolve(cur()),...readForm(form)});root.querySelector('#skipAccessPrefs').onclick=()=>setStatus(status,'Skipped. No profile was created and core access is unchanged.');root.querySelectorAll('[data-language-field]').forEach(button=>button.addEventListener('click',()=>{setErrors(errors);applyLanguageSelection(root,button.dataset.languageField,button.dataset.languageCode);try{setStatus(status,'Saving…','saving');save(readForm(form),{expectedVersion:profile()?.version??null,section:'LANGUAGE'});setStatus(status,'Saved','saved');if(retry)retry.hidden=true;render()}catch(err){setErrors(errors,err.message);setStatus(status,'Could not save','error');if(retry)retry.hidden=false}}));root.querySelectorAll('[data-reading-preset]').forEach(button=>button.addEventListener('click',()=>{const preset=READING_COMFORT_PRESETS[button.dataset.readingPreset];if(!preset)return;for(const [field,value] of Object.entries(preset.patch)){const control=form.elements[field];if(!control)continue;if(control.type==='checkbox')control.checked=Boolean(value);else control.value=value}setRadioState(root,'[data-reading-preset]',item=>item.dataset.readingPreset===button.dataset.readingPreset);Object.entries(preset.patch).forEach(([field,value])=>setRadioState(root,`[data-pref-field="${field}"]`,item=>item.dataset.prefValue===String(value)));applyReadingPreview(root,readForm(form));setStatus(status,'Preset preview updated. Save when ready.') }));root.querySelectorAll('[data-pref-field]').forEach(button=>button.addEventListener('click',()=>{const hidden=form.elements[button.dataset.prefField];if(hidden)hidden.value=button.dataset.prefValue;setRadioState(root,`[data-pref-field="${button.dataset.prefField}"]`,item=>item.dataset.prefValue===button.dataset.prefValue);markCustomPreset(root);applyReadingPreview(root,readForm(form));setStatus(status,'Preview updated. Save when ready.')}));root.querySelectorAll('[data-reading-select]').forEach(control=>control.addEventListener('change',()=>{markCustomPreset(root);applyReadingPreview(root,readForm(form));setStatus(status,'Preview updated. Save when ready.')}));['readingRulerEnabled','currentReadingHighlightEnabled','reduceVisualClutter','reducedMotionEnabled','oneInstructionAtATimeEnabled','preserveAcademicTerminology','reduceItalicText','disableDecorativeFonts'].forEach(name=>{form.elements[name]?.addEventListener('change',()=>{if(name!=='preserveAcademicTerminology')markCustomPreset(root);applyReadingPreview(root,readForm(form));setStatus(status,'Preview updated. Save when ready.')})});root.querySelector('#previewAccessPrefs').onclick=()=>{try{const values=readForm(form);apply(preview(values).preferences);applyReadingPreview(root,values);setStatus(status,'Preview applied temporarily. Not saved.')}catch(e){setErrors(errors,e.message)}};form.onsubmit=e=>{e.preventDefault();try{setErrors(errors);setStatus(status,'Saving…','saving');save(readForm(form),{expectedVersion:profile()?.version??null});setStatus(status,'Saved','saved');if(retry)retry.hidden=true;render()}catch(err){setErrors(errors,err.message);setStatus(status,'Could not save','error');if(retry)retry.hidden=false}};if(retry)retry.onclick=()=>form.requestSubmit?.();root.querySelector('#resetAccessPrefs').onclick=()=>{if(confirm('Reset all preferences?')){reset();render()}};const readingReset=root.querySelector('#resetReadingComfort');if(readingReset)readingReset.onclick=()=>{if(confirm('Reset reading comfort settings? Language and account preferences will stay unchanged.')){['readingComfortPreset','textScale','accessibleFontPreference','contrastTheme','lineSpacing','letterSpacing','wordSpacingPreference','contentWidth','paragraphSpacing','readingRulerStyle','readingRulerSize','currentReadingHighlightMode'].forEach(field=>{if(form.elements[field])form.elements[field].value=DEFAULTS[field]||READING_COMFORT_PRESETS.DEFAULT.patch[field]||'DEFAULT'});['readingRulerEnabled','reduceVisualClutter','oneInstructionAtATimeEnabled','reduceItalicText','disableDecorativeFonts'].forEach(field=>{if(form.elements[field])form.elements[field].checked=Boolean(DEFAULTS[field])});applyReadingPreview(root,readForm(form));setRadioState(root,'[data-reading-preset]',item=>item.dataset.readingPreset==='DEFAULT');root.querySelector('.reading-active-preset')&&(root.querySelector('.reading-active-preset').textContent='Active preset: Default');setStatus(status,'Reading comfort reset. Save when ready.')}}}
